```rust
use wgpu::{Surface, SurfaceConfiguration, Adapter, Instance};
use wgpu::util::BackendBit;
use wgpu_ui::{Builder, Theme};
use tokio;
use rand;
use std::env;
use std::sync::mpsc;

const WIDTH: u32 = 800;
const HEIGHT: u32 = 600;

fn main() {
    env::set_var("WGPU_INSTANCE_EXPOSE_WEBGL_LAYER", "1");
    let (window, surface, instance, adapter, device, queue) = create_window();
    let (tx, rx) = mpsc::channel();
    let thread = tokio::spawn(async move {
        let mut builder = Builder::new(rx);
        let mut theme = Theme::new();
        let ui = builder.create_ui(theme);
        let render_pass = device.create_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("Render Pass"),
            color_attachments: &[wgpu::RenderPassColorAttachment {
                view: &ui.view,
                resolve_target: None,
                load_op: wgpu::LoadOp::Clear,
                store_op: wgpu::StoreOp::Store,
                clear_color: wgpu::Color { r: 0.0, g: 0.0, b: 0.0, a: 1.0 },
            }],
            depth_stencil_attachment: None,
        });
        loop {
            let events = ui.poll_events();
            for event in events {
                tx.send(event).unwrap();
            }
            render_pass.execute(&ui.layout);
            ui.draw();
        }
    });
    tokio::select! {
        _ = thread => todo!("thread finished"),
        event = tx.recv() => {
            match event {
                wgpu_ui::Event::MouseMoved { x, y } => {
                    println!("Mouse moved to ({}, {})", x, y);
                }
                wgpu_ui::Event::Resized { width, height } => {
                    println!("Window resized to ({}, {})", width, height);
                }
                wgpu_ui::Event::Closed => {
                    println!("Window closed");
                    break;
                }
                _ => {}
            }
        }
    }
    queue.submit(&[device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("Root Stage"),
    })]).await.unwrap();
    surface.destroy();
    window.close();
}

fn create_window() -> (Window, Surface, Instance, Adapter, Device, Queue) {
    let instance = Instance::new(BackendBit::PRIMARY);
    let (window, surface) = unsafe { instance.create_surface(Window::new(WIDTH, HEIGHT, &WindowBuilder::new().build(), &Default::default())); };
    let adapter = instance.request_adapter(BackendBit::PRIMARY).expect("Failed to find an adapter");
    let (device, queue) = adapter.request_device(&[DeviceDescriptor {
        label: None,
        features: DeviceFeatures::default(),
        limits: Limits::downlevel_webgl2(),
    }], None).unwrap();
    (window, surface, instance, adapter, device, queue)
}

struct Window {
    handle: wgpu::Window,
}

struct Theme {
    color: (f32, f32, f32, f32),
}

impl Theme {
    fn new() -> Self {
        Theme { color: (0.0, 0.0, 0.0, 1.0) }
    }
}
```

